#!/usr/bin/env python3
"""
Genera recetas/receta-<slug>.html a partir del template de pisto y una lista
de recetas definida en RECETAS. Uso interno: se regenera cada vez que se
añaden nuevas recetas y luego se ejecuta generar-recetas.py para el manifiesto.
"""

import json
import re
from pathlib import Path

