# ---------------------------------------------------------------------------
# Renderizado
# ---------------------------------------------------------------------------

def a_meta_receta(r):
    """Construye el bloque JSON que el índice lee para categoría y búsqueda."""
    return {
        "id": r["id"],
        "nombre": r["nombre"],
        "tipo": {"id": r["tipo"][0], "nombre": r["tipo"][1]},
        "aparato": "Thermomix" if r.get("modelos") else "Tradicional",
        "modelos": r.get("modelos", []),
        "raciones": r["raciones"],
        "tiempoTotal": r["tiempos"][1],
        "tiempoPreparacion": r["tiempos"][0],
        "dificultad": r.get("dificultad", ""),
        "ingredientes": [ing[1] for ing in r["ingredientes"]],
        "etiquetas": r.get("etiquetas", []),
    }


def a_receta_js(r):
    """Construye el objeto RECETA que consume la propia página de la receta."""
    return {
        "id": r["id"],
        "nombre": r["nombre"],
        "tipo": {"id": r["tipo"][0], "nombre": r["tipo"][1]},
        "aparato": "Thermomix" if r.get("modelos") else "Tradicional",
        "modelos": r.get("modelos", []),
        "racionesBase": r["raciones"],
        "tiempos": {"preparacion": r["tiempos"][0], "total": r["tiempos"][1]},
        "ingredientes": [
            {"id": i[0], "nom": i[1], "prep": i[2], "cant": i[3], "uni": i[4]}
            for i in r["ingredientes"]
        ],
        "pasos": [
            {"titulo": p[0], "texto": p[1],
             "ajustes": [{"t": a[0], "c": a[1]} for a in p[2]],
             "seg": p[3]}
            for p in r["pasos"]
        ],
        "servir": r.get("servir", ""),
    }


def render(receta, plantilla):
    """Sustituye el título, el bloque meta-receta y el objeto RECETA."""
    html = plantilla

    # 1) <title>
    html = re.sub(
        r"<title>[^<]*</title>",
        f"<title>{receta['nombre']} · Recetario Thermomix</title>",
        html, count=1,
    )

    # 2) meta-receta (lambda para evitar que re.sub interprete escapes)
    meta_json = json.dumps(a_meta_receta(receta), ensure_ascii=False, indent=2)
    reemplazo_meta = '<script type="application/json" id="meta-receta">\n' + meta_json + '\n</script>'
    html = re.sub(
        r'<script type="application/json" id="meta-receta">[\s\S]*?</script>',
        lambda _: reemplazo_meta,
        html, count=1,
    )

    # 3) var RECETA = {...};  (anclado al comentario /* rutas que le sigue).
    # Usamos una lambda como replacement para que re.sub NO interprete
    # secuencias de escape (\n, \t, \g<0>...) presentes en el JSON serializado.
    receta_json = json.dumps(a_receta_js(receta), ensure_ascii=False, indent=2)
    reemplazo_receta = "var RECETA = " + receta_json + ";\n\n  "
    nuevo, n = re.subn(
        r"var RECETA = \{[\s\S]*?\};\s*(?=/\* rutas)",
        lambda _: reemplazo_receta,
        html, count=1,
    )
    if n != 1:
        raise RuntimeError(f"No pude reemplazar var RECETA en {receta['id']}")
    html = nuevo

    return html


def main():
    plantilla = TEMPLATE.read_text(encoding="utf-8")
    escritas = 0
    for r in RECETAS:
        salida = DESTINO / f"receta-{r['id']}.html"
        salida.write_text(render(r, plantilla), encoding="utf-8")
        print(f"  · {r['nombre']:<52s}  →  {salida.relative_to(RAIZ)}")
        escritas += 1
    print(f"\nEscritas {escritas} recetas.")


if __name__ == "__main__":
    main()
